INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('power-quest','intermediate','What is a three-phase system?',ARRAY['Three AC voltages 120° apart','Three DC voltages','Single-phase with three wires','Three batteries in series'],0,'Three-phase: balanced 120° phase separation.',15),
('power-quest','intermediate','What is the advantage of three-phase power?',ARRAY['More efficient for power transmission','Higher voltage','Lower frequency','Better power factor'],0,'Three-phase delivers constant instantaneous power.',15),
('power-quest','intermediate','What is the line voltage in a Y-connected system?',ARRAY['√3 × phase voltage','Same as phase voltage','2 × phase voltage','Phase voltage / √3'],0,'Y-connection: Vline = √3 × Vphase.',15),
('power-quest','intermediate','What is the line current in a Δ-connected system?',ARRAY['√3 × phase current','Same as phase current','2 × phase current','Phase current / √3'],0,'Δ-connection: Iline = √3 × Iphase.',15),
('power-quest','intermediate','What is the total power in a balanced three-phase system?',ARRAY['√3 × Vline × Iline × cos(φ)','Vline × Iline','3 × Vphase × Iphase','√3 × Vline × Iline'],0,'3-phase power: P = √3 × VL × IL × cos(φ).',15),
('power-quest','intermediate','What is the relationship between line and phase voltage in Y?',ARRAY['Vline = √3 × Vphase','Vline = Vphase','Vline = 2 × Vphase','Vline = Vphase/√3'],0,'Y: line voltage = √3 × phase voltage.',15),
('power-quest','intermediate','What is the relationship between line and phase current in Y?',ARRAY['Iline = Iphase','Iline = √3 × Iphase','Iline = 2 × Iphase','Iline = Iphase/√3'],0,'Y: line current = phase current.',15),
('power-quest','intermediate','What is the relationship between line and phase voltage in Δ?',ARRAY['Vline = Vphase','Vline = √3 × Vphase','Vline = 2 × Vphase','Vline = Vphase/√3'],0,'Δ: line voltage = phase voltage.',15),
('power-quest','intermediate','What is the relationship between line and phase current in Δ?',ARRAY['Iline = √3 × Iphase','Iline = Iphase','Iline = 2 × Iphase','Iline = Iphase/√3'],0,'Δ: line current = √3 × phase current.',15),
('power-quest','intermediate','What is power factor correction?',ARRAY['Adding capacitors to improve PF','Adding inductors','Adding resistors','Adding transformers'],0,'PFC capacitors cancel inductive reactive power.',15),
('power-quest','intermediate','Why improve power factor?',ARRAY['Reduce current and losses','Increase voltage','Increase power','Reduce frequency'],0,'Better PF → lower current → lower I²R losses.',15),
('power-quest','intermediate','What is the capacitance needed for PFC?',ARRAY['C = Q/(2πfV²)','C = Q/V','C = V/Q','C = Q×V'],0,'Required C = reactive power / (2πf × V²).',15),
('power-quest','intermediate','What is the maximum efficiency of a transformer?',ARRAY['At load where copper loss = core loss','At full load','At no load','At half load'],0,'Max efficiency when variable losses = constant losses.',15),
('power-quest','intermediate','What is per-unit system?',ARRAY['Normalizing values to a base','Unit system for power','SI units','Percentage system'],0,'Per-unit simplifies calculations by normalizing.',15),
('power-quest','intermediate','What is the base value in per-unit system?',ARRAY['Reference for normalization','Maximum value','Minimum value','Average value'],0,'Base values: Vbase, Ibase, Sbase, Zbase.',15),
('power-quest','intermediate','What is a synchronous generator?',ARRAY['Generator with rotor at synchronous speed','Generator with variable speed','DC generator','Induction generator'],0,'Alternator: rotor speed = synchronous speed.',15),
('power-quest','intermediate','What is synchronous speed?',ARRAY['Ns = 120f/P','Ns = 60f/P','Ns = f/P','Ns = 120P/f'],0,'Ns = 120 × frequency / poles.',15),
('power-quest','intermediate','What is the synchronous speed of a 4-pole machine at 60 Hz?',ARRAY['1800 RPM','3600 RPM','900 RPM','1200 RPM'],0,'Ns = 120 × 60 / 4 = 1800 RPM.',15),
('power-quest','intermediate','What is the synchronous speed of a 2-pole machine at 50 Hz?',ARRAY['3000 RPM','1500 RPM','1000 RPM','750 RPM'],0,'Ns = 120 × 50 / 2 = 3000 RPM.',15),
('power-quest','intermediate','What is an induction motor?',ARRAY['Motor where rotor speed < synchronous speed','Motor at synchronous speed','DC motor','Universal motor'],0,'Induction motor: rotor runs below synchronous speed.',15),
('power-quest','intermediate','What is slip in an induction motor?',ARRAY['(Ns - Nr) / Ns × 100%','Ns / Nr','Nr / Ns','Ns - Nr'],0,'Slip s = (Ns - Nr) / Ns.',15),
('power-quest','intermediate','What is the slip of an induction motor at no load?',ARRAY['~0%','100%','50%','10%'],0,'At no load, rotor nearly reaches synchronous speed.',15),
('power-quest','intermediate','What is the slip at motor startup?',ARRAY['100% (or 1)','0%','50%','10%'],0,'At start, rotor is stationary, so slip = 1.',15),
('power-quest','intermediate','What is the typical slip at full load?',ARRAY['2-5%','0%','50%','100%'],0,'Full load slip is small (2-5%).',15),
('power-quest','intermediate','What is the torque-slip characteristic?',ARRAY['Torque varies with slip','Torque is constant','Torque decreases with slip','No relationship'],0,'Torque increases with slip up to maximum torque.',15),
('power-quest','intermediate','What is the starting torque of an induction motor?',ARRAY['Torque at slip = 1','Torque at slip = 0','Maximum torque','Rated torque'],0,'Starting torque = torque at standstill (s=1).',15),
('power-quest','intermediate','What is the maximum torque called?',ARRAY['Pull-out (breakdown) torque','Starting torque','Rated torque','Full-load torque'],0,'Pull-out torque is the maximum the motor can produce.',15),
('power-quest','intermediate','How do you start a large induction motor?',ARRAY['Star-delta or auto-transformer starter','Direct online','Always direct','Series resistor'],0,'Large motors need reduced-voltage starting to limit current.',15),
('power-quest','intermediate','What is a star-delta starter?',ARRAY['Starts in Y, runs in Δ','Starts in Δ, runs in Y','Always Y','Always Δ'],0,'Y-Δ starter reduces starting voltage by 1/√3.',15),
('power-quest','intermediate','What is the starting current reduction in Y-Δ starting?',ARRAY['1/3 of DOL current','1/2 of DOL','2/3 of DOL','Same as DOL'],0,'Y starting: current = 1/3 of direct-on-line.',15),
('power-quest','intermediate','What is a VFD?',ARRAY['Variable Frequency Drive','Voltage Frequency Detector','Variable Force Drive','Voltage Feedback Device'],0,'VFD controls motor speed by varying frequency/voltage.',15),
('power-quest','intermediate','How does a VFD control motor speed?',ARRAY['By varying frequency and voltage','By varying current only','By varying resistance','By varying load'],0,'VFD: ns = 120f/P, so speed ∝ frequency.',15),
('power-quest','intermediate','What is PWM in power electronics?',ARRAY['Pulse Width Modulation','Power Wave Modulation','Pulse Wave Management','Phase Width Modulation'],0,'PWM varies duty cycle to control average voltage.',15),
('power-quest','intermediate','What is the purpose of PWM in inverters?',ARRAY['Control output voltage and reduce harmonics','Increase frequency','Reduce voltage','Increase current'],0,'PWM synthesizes sinusoidal output from DC.',15),
('power-quest','intermediate','What is SPWM?',ARRAY['Sinusoidal PWM','Synchronous PWM','Simple PWM','Symmetric PWM'],0,'SPWM: sine reference compared with triangular carrier.',15),
('power-quest','intermediate','What is the THD of an ideal sine wave inverter?',ARRAY['0%','5%','10%','3%'],0,'Ideal sine wave has no harmonics.',15),
('power-quest','intermediate','What is a snubber circuit?',ARRAY['Protects switches from voltage spikes','Increases switching speed','Reduces power','Measures voltage'],0,'Snubbers absorb transients from parasitic inductance.',15),
('power-quest','intermediate','What is a flyback diode?',ARRAY['Protects against inductive kickback','Rectifies AC','Filters noise','Stores charge'],0,'Flyback diode provides path for inductor current.',15),
('power-quest','intermediate','What is soft switching?',ARRAY['Zero voltage or zero current switching','Low voltage switching','Slow switching','Low power switching'],0,'Soft switching reduces switching losses.',15),
('power-quest','intermediate','What is ZVS?',ARRAY['Zero Voltage Switching','Zero Voltage Source','Zero Value Switch','Zener Voltage Switching'],0,'ZVS: switch transitions at zero voltage.',15),
('power-quest','intermediate','What is ZCS?',ARRAY['Zero Current Switching','Zero Current Source','Zero Circuit Switch','Zener Current Switching'],0,'ZCS: switch transitions at zero current.',15),
('power-quest','intermediate','What is a power MOSFET?',ARRAY['Voltage-controlled switching device','Current-controlled device','Bipolar device','Passive device'],0,'MOSFET: gate voltage controls drain-source current.',15),
('power-quest','intermediate','What is an IGBT?',ARRAY['Insulated Gate Bipolar Transistor','Integrated Gate Bipolar Transistor','Insulated Gate Buffered Transistor','Internal Gate Bipolar Transistor'],0,'IGBT combines MOSFET gate and BJT power handling.',15),
('power-quest','intermediate','What is the advantage of IGBT over MOSFET?',ARRAY['Higher voltage and current handling','Faster switching','Lower voltage','Lower cost'],0,'IGBT handles high power; MOSFET is faster.',15),
('power-quest','intermediate','What is the advantage of MOSFET over IGBT?',ARRAY['Faster switching at lower voltages','Higher voltage','Higher current','Better efficiency at high power'],0,'MOSFETs switch faster, better for low voltage.',15),
('power-quest','intermediate','What is a thyristor?',ARRAY['Latching semiconductor switch','Always-on switch','Voltage regulator','Current source'],0,'Thyristor: SCR, latches on until current stops.',15),
('power-quest','intermediate','What triggers a thyristor?',ARRAY['Gate pulse','Voltage at anode','Current at cathode','Removing gate signal'],0,'SCR turns on with gate pulse, off when current < holding.',15),
('power-quest','intermediate','What is a TRIAC?',ARRAY['Bidirectional thyristor','Unidirectional thyristor','DC switch','AC rectifier'],0,'TRIAC conducts in both directions (AC switch).',15),
('power-quest','intermediate','What is a DIAC?',ARRAY['Bidirectional trigger diode','Unidirectional diode','Zener diode','Schottky diode'],0,'DIAC triggers TRIACs when voltage reaches breakover.',15),
('power-quest','intermediate','What is the difference between linear and switching regulators?',ARRAY['Linear dissipates excess; switching chops','Linear is more efficient','Switching has more noise','No difference'],0,'Linear: simple, low noise, less efficient. Switching: efficient, noisy.',15);